#include <WiFi.h>
#include <secrets.h>

const char* WIFI_SSID = "DIR-615T-0DBC";
const char* WIFI_PASS = "23233010";

IPAddress PC_IP(192, 168, 1, 100);
const int PC_PORT = 8080;

#define BTN_PIN 0
#define LED_PIN 48

void setup() {
  Serial.begin(115200);
  delay(1000);

  pinMode(BTN_PIN, INPUT_PULLUP);
  neopixelWrite(LED_PIN, 0, 0, 0);

  WiFi.mode(WIFI_STA);
  WiFi.setTxPower(WIFI_POWER_8_5dBm);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  while (WiFi.status() != WL_CONNECTED) {
    delay(300);
    Serial.print(".");
  }
  Serial.print("\nПодключено. IP: ");
  Serial.println(WiFi.localIP());
}

void sendSignal() {
  WiFiClient client;
  client.setTimeout(2000);
  if (client.connect(PC_IP, PC_PORT)) {
    client.println("SHUTDOWN");
    client.stop();
    Serial.println("Сигнал отправлен");
  } else {
    Serial.println("ПК недоступен — Java-сервер запущен?");
  }
}

void loop() {
  if (digitalRead(BTN_PIN) == LOW) {
    delay(40);
    if (digitalRead(BTN_PIN) == LOW) {
      neopixelWrite(LED_PIN, 255, 0, 0);
      sendSignal();
      delay(5000);
      neopixelWrite(LED_PIN, 0, 0, 0);
      while (digitalRead(BTN_PIN) == LOW) delay(10);
    }
  }
}
